spinner.css:
.spinner {
    width: 40px;
    height: 40px;
    border: 4px solid #f3f3f3;
    border-top: 4px solid #3498db;
    border-radius: 50%;
    animation: spin 1s linear infinite;
}
@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

dots.css:
.dots {
    display: flex;
    gap: 8px;
    align-items: center;
}
.dot {
    width: 12px;
    height: 12px;
    background: #3498db;
    border-radius: 50%;
    animation: bounce 1.4s infinite ease-in-out both;
}
.dot:nth-child(1) { animation-delay: -0.32s; }
.dot:nth-child(2) { animation-delay: -0.16s; }
@keyframes bounce {
    0%, 80%, 100% { transform: scale(0); }
    40% { transform: scale(1); }
}

pulse.css:
.pulse {
    width: 40px;
    height: 40px;
    background: #3498db;
    border-radius: 50%;
    animation: pulse 1.2s ease-in-out infinite;
}
@keyframes pulse {
    0% { transform: scale(0.5); opacity: 1; }
    100% { transform: scale(1.2); opacity: 0; }
}

bars.css:
.bars {
    display: flex;
    gap: 4px;
    align-items: center;
    height: 40px;
}
.bar {
    width: 6px;
    height: 100%;
    background: #3498db;
    animation: bar-pulse 1s ease-in-out infinite;
}
.bar:nth-child(1) { animation-delay: 0s; }
.bar:nth-child(2) { animation-delay: 0.1s; }
.bar:nth-child(3) { animation-delay: 0.2s; }
.bar:nth-child(4) { animation-delay: 0.3s; }
.bar:nth-child(5) { animation-delay: 0.4s; }
@keyframes bar-pulse {
    0%, 100% { transform: scaleY(0.4); }
    50% { transform: scaleY(1); }
}

ring.css:
.ring {
    width: 40px;
    height: 40px;
    border: 4px solid rgba(52, 152, 219, 0.2);
    border-top-color: #3498db;
    border-radius: 50%;
    animation: ring-spin 1s linear infinite;
}
@keyframes ring-spin {
    to { transform: rotate(360deg); }
}

dual-ring.css:
.dual-ring {
    width: 44px;
    height: 44px;
    position: relative;
}
.dual-ring, .dual-ring-inner {
    border: 4px solid transparent;
    border-radius: 50%;
}
.dual-ring {
    border-top-color: #3498db;
    animation: dual-spin 1.2s linear infinite;
}
.dual-ring-inner {
    position: absolute;
    top: 4px; left: 4px; right: 4px; bottom: 4px;
    border-bottom-color: #e74c3c;
    animation: dual-spin 0.8s linear infinite reverse;
}
@keyframes dual-spin {
    to { transform: rotate(360deg); }
}

grid.css:
.grid-loader {
    display: grid;
    grid-template-columns: repeat(3, 12px);
    gap: 4px;
}
.grid-cell {
    width: 12px;
    height: 12px;
    background: #3498db;
    animation: grid-fade 1.3s ease-in-out infinite;
}
.grid-cell:nth-child(1) { animation-delay: 0s; }
.grid-cell:nth-child(2) { animation-delay: 0.1s; }
.grid-cell:nth-child(3) { animation-delay: 0.2s; }
.grid-cell:nth-child(4) { animation-delay: 0.1s; }
.grid-cell:nth-child(5) { animation-delay: 0.2s; }
.grid-cell:nth-child(6) { animation-delay: 0.3s; }
.grid-cell:nth-child(7) { animation-delay: 0.2s; }
.grid-cell:nth-child(8) { animation-delay: 0.3s; }
.grid-cell:nth-child(9) { animation-delay: 0.4s; }
@keyframes grid-fade {
    0%, 70%, 100% { opacity: 0.3; transform: scale(0.6); }
    35% { opacity: 1; transform: scale(1); }
}

skeleton.css:
.skeleton {
    display: flex;
    flex-direction: column;
    gap: 10px;
    width: 200px;
}
.skeleton-line {
    height: 14px;
    background: linear-gradient(90deg, #e0e0e0 25%, #f0f0f0 50%, #e0e0e0 75%);
    background-size: 200% 100%;
    border-radius: 4px;
    animation: shimmer 1.5s infinite;
}
.skeleton-line-lg { width: 100%; }
.skeleton-line-md { width: 80%; }
.skeleton-line-sm { width: 50%; }
@keyframes shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

orbit.css:
.orbit {
    width: 48px;
    height: 48px;
    position: relative;
}
.orbit-center {
    width: 12px;
    height: 12px;
    background: #3498db;
    border-radius: 50%;
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
}
.orbit-ring {
    width: 100%;
    height: 100%;
    border: 3px solid rgba(52, 152, 219, 0.2);
    border-top-color: #3498db;
    border-radius: 50%;
    animation: ring-spin 1s linear infinite;
}

wave.css:
.wave {
    display: flex;
    gap: 3px;
    align-items: center;
    height: 40px;
}
.wave-bar {
    width: 4px;
    height: 20px;
    background: #3498db;
    border-radius: 2px;
    animation: wave-anim 1.2s ease-in-out infinite;
}
.wave-bar:nth-child(1) { animation-delay: 0s; }
.wave-bar:nth-child(2) { animation-delay: 0.1s; }
.wave-bar:nth-child(3) { animation-delay: 0.2s; }
.wave-bar:nth-child(4) { animation-delay: 0.3s; }
.wave-bar:nth-child(5) { animation-delay: 0.4s; }
@keyframes wave-anim {
    0%, 100% { height: 20px; }
    50% { height: 40px; }
}

progress.css:
.progress-container {
    width: 200px;
    height: 6px;
    background: #e0e0e0;
    border-radius: 3px;
    overflow: hidden;
}
.progress-bar {
    width: 40%;
    height: 100%;
    background: #3498db;
    border-radius: 3px;
    animation: progress-slide 1.5s ease-in-out infinite;
}
@keyframes progress-slide {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(350%); }
}

heartbeat.css:
.heartbeat {
    font-size: 32px;
    color: #e74c3c;
    animation: heartbeat 1.2s ease-in-out infinite;
}
@keyframes heartbeat {
    0%, 100% { transform: scale(1); }
    14% { transform: scale(1.3); }
    28% { transform: scale(1); }
    42% { transform: scale(1.3); }
    70% { transform: scale(1); }
}

ellipsis.css:
.ellipsis {
    display: flex;
    gap: 4px;
    font-size: 28px;
    font-weight: bold;
    color: #3498db;
}
.ellipsis-dot {
    width: 8px;
    height: 8px;
    background: #3498db;
    border-radius: 50%;
    animation: ellipsis-bounce 1.4s infinite ease-in-out both;
}
.ellipsis-dot:nth-child(1) { animation-delay: -0.32s; }
.ellipsis-dot:nth-child(2) { animation-delay: -0.16s; }
.ellipsis-dot:nth-child(3) { animation-delay: 0s; }
.ellipsis-dot:nth-child(4) { animation-delay: 0.16s; }
@keyframes ellipsis-bounce {
    0%, 80%, 100% { transform: scale(0.4); opacity: 0.4; }
    40% { transform: scale(1); opacity: 1; }
}

cube.css:
.cube-loader {
    width: 40px;
    height: 40px;
    position: relative;
    transform-style: preserve-3d;
    animation: cube-rotate 2s linear infinite;
}
.cube-face {
    position: absolute;
    width: 40px;
    height: 40px;
    background: rgba(52, 152, 219, 0.8);
    border: 2px solid rgba(255,255,255,0.3);
}
.cube-front  { transform: translateZ(20px); }
.cube-back   { transform: rotateY(180deg) translateZ(20px); }
.cube-right  { transform: rotateY(90deg) translateZ(20px); }
.cube-left   { transform: rotateY(-90deg) translateZ(20px); }
.cube-top    { transform: rotateX(90deg) translateZ(20px); }
.cube-bottom { transform: rotateX(-90deg) translateZ(20px); }
@keyframes cube-rotate {
    0% { transform: rotateX(0deg) rotateY(0deg); }
    100% { transform: rotateX(360deg) rotateY(360deg); }
}
